mapper.select:
SELECT r.user_id, u.nickname, d.dept_name, r.recency_days, r.frequency, r.monetary,
       r.r_score, r.f_score, r.m_score, r.segment, r.calc_date
FROM stat_user_rfm r
LEFT JOIN sys_user u ON u.user_id = r.user_id
LEFT JOIN sys_dept d ON d.dept_id = u.dept_id
WHERE r.calc_date = #{calcDate}

    AND r.segment = #{segment}

ORDER BY r.monetary DESC, r.frequency DESC, r.user_id ASC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM stat_user_rfm
WHERE calc_date = #{calcDate}

    AND segment = #{segment}

SELECT COUNT(*) AS user_count, IFNULL(SUM(monetary), 0) AS monetary
FROM stat_user_rfm
WHERE calc_date = #{calcDate}
